 function faceBot(s,dx,dz,dt){if(Math.hypot(dx,dz)<.001)return;let desired=Math.atan2(dx,-dz),delta=Math.atan2(Math.sin(desired-s.group.rotation.y),Math.cos(desired-s.group.rotation.y));s.group.rotation.y+=delta*Math.min(1,dt*5)}
