import json, socket, struct, base64, os, urllib.request, time

class WS:
    def __init__(self, url):
        from urllib.parse import urlparse
        u=urlparse(url); self.s=socket.create_connection((u.hostname,u.port)); key=base64.b64encode(os.urandom(16)).decode()
        req=f"GET {u.path} HTTP/1.1\r\nHost: {u.hostname}:{u.port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n\r\n"
        self.s.sendall(req.encode()); data=b''
        while b'\r\n\r\n' not in data: data+=self.s.recv(4096)
        if b' 101 ' not in data.split(b'\r\n',1)[0]: raise RuntimeError(data[:500])
        self.i=0
    def send(self, obj):
        b=json.dumps(obj).encode(); mask=os.urandom(4); n=len(b)
        head=bytes([0x81,0x80|(n if n<126 else 126 if n<65536 else 127)])
        if n>=126: head+=struct.pack('!H' if n<65536 else '!Q',n)
        self.s.sendall(head+mask+bytes(v^mask[i%4] for i,v in enumerate(b)))
    def recv(self):
        while True:
            h=self._read(2); n=h[1]&127
            if n==126:n=struct.unpack('!H',self._read(2))[0]
            elif n==127:n=struct.unpack('!Q',self._read(8))[0]
            mask=self._read(4) if h[1]&128 else None; b=self._read(n)
            if mask:b=bytes(v^mask[i%4] for i,v in enumerate(b))
            if h[0]&15==8: raise RuntimeError('websocket closed')
            if h[0]&15==1:return json.loads(b)
    def _read(self,n):
        b=b''
        while len(b)<n:b+=self.s.recv(n-len(b))
        return b

pages=json.load(urllib.request.urlopen('http://127.0.0.1:9222/json'))
page=next(p for p in pages if p['type']=='page' and p['url'].startswith('http://127.0.0.1:8765'))
ws=WS(page['webSocketDebuggerUrl']); seq=0; pending={}
def cmd(method,params=None):
    global seq
    seq+=1; i=seq; ws.send({'id':i,'method':method,'params':params or {}})
    while True:
        m=ws.recv()
        if m.get('id')==i:
            if 'error' in m: raise RuntimeError(m['error'])
            return m.get('result',{})
def ev(expr, await_promise=False):
    r=cmd('Runtime.evaluate',{'expression':expr,'returnByValue':True,'awaitPromise':await_promise})
    if r.get('exceptionDetails'): raise RuntimeError(r['exceptionDetails'])
    return r.get('result',{}).get('value')
def wait(sec): time.sleep(sec)
cmd('Emulation.setDeviceMetricsOverride',{'width':844,'height':390,'deviceScaleFactor':1,'mobile':True})
cmd('Emulation.setTouchEmulationEnabled',{'enabled':True,'maxTouchPoints':5})
wait(3)
print('initial',ev("JSON.stringify({touch:document.documentElement.className,controls:getComputedStyle(document.querySelector('.mobile-controls')).display,menu:document.querySelector('#menuScreen').className,canvas:!!document.querySelector('canvas').getContext('webgl2')})"))
ev("document.querySelector('#rotBtn').click()")
ev("document.querySelector('#playBtn').click()")
ev("document.querySelector('#deploy').click()")
wait(2)
print('in-game',ev("JSON.stringify({hud:document.querySelector('#hud').className,controls:getComputedStyle(document.querySelector('.mobile-controls')).display,stick:(()=>{let r=document.querySelector('#stick').getBoundingClientRect();return [r.x,r.y,r.width,r.height]})(),aim:(()=>{let r=document.querySelector('#aimStick').getBoundingClientRect();return [r.x,r.y,r.width,r.height]})(),ammo:document.querySelector('#ammo').innerText, player:typeof player!=='undefined'?player.position.toArray():null})"))
def box(selector): return ev(f"(()=>{{let r=document.querySelector('{selector}').getBoundingClientRect();return {{x:r.x+r.width/2,y:r.y+r.height/2,w:r.width,h:r.height}}}})()")
def touch(kind, x,y, ident=1):
    p={'x':x,'y':y,'id':ident,'radiusX':3,'radiusY':3,'force':1}
    cmd('Input.dispatchTouchEvent',{'type':kind,'touchPoints':[p] if kind!='touchEnd' else []})
def begin(selector, ident=1):
    p=box(selector); touch('touchStart',p['x'],p['y'],ident); return p
def move(selector, dx,dy, ident=1):
    p=box(selector); touch('touchStart',p['x'],p['y'],ident); touch('touchMove',p['x']+dx,p['y']+dy,ident)
def end(): cmd('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]})
# left joystick hold upward, check movement then release
p=box('#stick'); startpos=ev('player.position.toArray()'); touch('touchStart',p['x'],p['y']); touch('touchMove',p['x'],p['y']-35); wait(1); moved=ev('player.position.toArray()'); end(); wait(.2)
print('move',startpos,'=>',moved,'stick:',ev("document.querySelector('#stick').style.getPropertyValue('--stick-y')"))
# sustained fire hold
ammo0=ev('ammo'); p=box('#fireTouch'); touch('touchStart',p['x'],p['y']); wait(.6); ammo1=ev('ammo'); end(); wait(.15)
print('fire ammo',ammo0,'=>',ammo1)
# reload
p=box('#reloadTouch'); touch('touchStart',p['x'],p['y']); touch('touchEnd',p['x'],p['y']); wait(1.3)
print('reload ammo',ev('ammo'))
# move toward vehicle until in range then tap use and drive briefly then exit
p=box('#stick'); touch('touchStart',p['x'],p['y']); touch('touchMove',p['x'],p['y']-35); wait(1.4); end(); wait(.2)
print('near vehicle',ev("JSON.stringify({d:player.position.distanceTo(vehicle.position),button:document.querySelector('#vehicleTouch').className})"))
ve=box('#vehicleTouch'); touch('touchStart',ve['x'],ve['y']); touch('touchEnd',ve['x'],ve['y']); wait(.2)
print('boarded',ev("JSON.stringify({driving,toast:document.querySelector('#toast').innerText})"))
p=box('#stick'); touch('touchStart',p['x'],p['y']); touch('touchMove',p['x'],p['y']-35); wait(.5); end()
print('tank moved',ev("JSON.stringify({driving,p:player.position.toArray(),v:vehicle.position.toArray()})"))
ve=box('#vehicleTouch'); touch('touchStart',ve['x'],ve['y']); touch('touchEnd',ve['x'],ve['y']); wait(.1)
print('exit',ev('driving'))

